	{
		navVector = player.inputDevice.GetMoveVector();
		if (inputReceived && navVector.sqrMagnitude < 0.04f)
		{
			inputReceived = false;
		}
		else if (!inputReceived && navVector.y < 0f && navVector.sqrMagnitude > 0.09f)
		{
			inputReceived = true;
			SoundManager.PlayAudio("MenuMove");
			SwapFocus(givenStatus: false);
		}
	}

	private void SwapFocus(bool givenStatus)
	{
		SetFocus(givenStatus);
		equipMenu.SetFocus(!givenStatus);
		inventoryMenu.SetFocus(status: false);
