	public virtual void Update()
	{
		if (useRefreshTimer && waitingForRefresh)
		{
			if (ChaosStopwatch.Check(refreshStopwatchID))
			{
				waitingForRefresh = false;
				spawnAnimPlayed = false;
				if (useDuration)
				{
					(durationStopwatch = new ChaosQuickStopwatch(duration)).IsRunning = true;
				}
				if (useReflectCount)
				{
					availableReflectCount = ogReflectCount;
				}
			}
		}
		else if (!spawnAnimPlayed)
